From 87adee05fcce62c751e28d9418696b44c9313117 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:52:50 +0100
Subject: [PATCH] libtaskmanager: let ungrouped pinned windows move in the
 whole pinned area

With launch-in-place sorting, the barrier between pinned and unpinned tasks
was the number of launchers, but without grouping one launcher can be shown
as several windows. The barrier now counts the launcher-backed rows instead.

BUG: 501112
---
 libtaskmanager/tasksmodel.cpp | 13 ++++++++++++-
 1 file changed, 12 insertions(+), 1 deletion(-)

diff --git a/libtaskmanager/tasksmodel.cpp b/libtaskmanager/tasksmodel.cpp
index fd6246a363..5f11b5766a 100644
--- a/libtaskmanager/tasksmodel.cpp
+++ b/libtaskmanager/tasksmodel.cpp
@@ -1659,7 +1659,18 @@ bool TasksModel::move(int row, int newPos, const QModelIndex &parent)
         int firstTask = 0;
         if (d->launcherTasksModel) {
             if (d->launchInPlace) {
-                firstTask = d->launcherTasksModel->rowCountForActivity(activity());
+                // Launcher-backed tasks take the place of their launcher, and there can be
+                // several of them per launcher when not grouping.
+                while (firstTask < rowCount()) {
+                    const QModelIndex &firstTaskIdx = index(firstTask, 0);
+
+                    if (!firstTaskIdx.data(AbstractTasksModel::IsLauncher).toBool()
+                        && launcherPosition(firstTaskIdx.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl()) == -1) {
+                        break;
+                    }
+
+                    ++firstTask;
+                }
             } else {
                 firstTask = launcherCount();
             }
